import sys

class University:
    class Student:
        def __init__(self, name, marks):
            self.name = name
            self.marks = marks

        def compute_grade(self):
            if self.marks >= 80:
                return 'A'
            elif self.marks >= 60:
                return 'B'
            else:
                return 'C'

    def __init__(self, name, marks):
        self.student = self.Student(name, marks)

    def get_grade(self):
        return self.student.compute_grade()

def main():
    line = sys.stdin.readline().strip()
    if not line:
        return
    parts = line.split()
    name = parts[0]
    marks = int(parts[1])

    uni = University(name, marks)
    print(uni.get_grade())

if __name__ == "__main__":
    main()
